import { pgTable, text, timestamp } from "drizzle-orm/pg-core";

// Homepage (docs/landingpage.md): the realistic pictures of the public pages,
// generated by the AI on the owner's request and stored like other photos.
// One row per slot (hero, bees, …); a new picture replaces the old one.
export const siteImagesTable = pgTable("site_images", {
  slot: text("slot").primaryKey(),
  url: text("url").notNull(),
  prompt: text("prompt").notNull(),
  model: text("model").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});
